import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    inf = n + 1

    # exact[x][L] is the smallest R of a condition (L,R,x).
    exact = [[inf] * n for _ in range(n)]
    at = 2
    for _ in range(m):
        l, r, x = data[at] - 1, data[at + 1] - 1, data[at + 2] - 1
        at += 3
        if r < exact[x][l]:
            exact[x][l] = r

    # bad[x][l] is the smallest R among conditions with X=x and L>=l.
    bad = [[inf] * n for _ in range(n)]
    for x in range(n):
        cur = inf
        for l in range(x, -1, -1):
            if exact[x][l] < cur:
                cur = exact[x][l]
            bad[x][l] = cur

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0 if bad[i][i] <= i else 1

    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            total = 0
            for root in range(l, r + 1):
                if bad[root][l] <= r:
                    continue
                left = dp[l][root - 1] if root > l else 1
                right = dp[root + 1][r] if root < r else 1
                total = (total + comb[length - 1][root - l] * left * right) % MOD
            dp[l][r] = total
    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

