import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:]]

    rev = [[] for _ in range(n)]
    indeg = [0] * n
    for i, p in enumerate(parent):
        rev[p].append(i)
        indeg[p] += 1

    queue = [i for i in range(n) if indeg[i] == 0]
    order = []
    for v in queue:
        order.append(v)
        p = parent[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    is_cycle = [x > 0 for x in indeg]
    dp = [None] * n

    # For a non-cycle vertex, dp[k] counts assignments in its subtree
    # whose value at the vertex is at most k.
    for v in order:
        prod = [1] * (m + 1)
        for child in rev[v]:
            if not is_cycle[child]:
                child_dp = dp[child]
                for k in range(1, m + 1):
                    prod[k] = prod[k] * child_dp[k] % MOD
        acc = 0
        for k in range(1, m + 1):
            acc = (acc + prod[k]) % MOD
            prod[k] = acc
        dp[v] = prod

    answer = 1
    seen = [False] * n
    for start in range(n):
        if not is_cycle[start] or seen[start]:
            continue
        cycle = []
        v = start
        while not seen[v]:
            seen[v] = True
            cycle.append(v)
            v = parent[v]

        # All vertices on this cycle must have the same value.
        prod = [1] * (m + 1)
        for v in cycle:
            for child in rev[v]:
                if not is_cycle[child]:
                    child_dp = dp[child]
                    for k in range(1, m + 1):
                        prod[k] = prod[k] * child_dp[k] % MOD
        answer = answer * (sum(prod[1:]) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

