    primes=set()
    for x in a:
        y=x; d=2
        while d*d<=y:
            if y%d==0:
                primes.add(d)
                while y%d==0: y//=d
            d+=1
        if y>1: primes.add(y)
    ans=1
    for p in primes:
        dp={(0,0):1}
        powers={0:1}
        def pw(k):
            if k not in powers: powers[k]=pow(p,k,MOD)
            return powers[k]
        for x in a:
            y=x; e=0
            while y%p==0:
                y//=p; e+=1
            if e==0:
                nd={}
                for key,v in dp.items():
                    c,m=key
                    nd[key]=v*pw(c)%MOD
                dp=nd
            else:
                nd={}
                for (c,m),v in dp.items():
                    q=v*pw(c+e)%MOD
                    key=(c+e, min(m,c+e))
