class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        # The two largest active left endpoints, together with their pair IDs.
        top_value = 0
        top_id = 0
        second_value = 0
        second_id = 0
        gain = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                if left >= top_value:
                    second_value, second_id = top_value, top_id
                    top_value, top_id = left, idx
                elif left > second_value:
                    second_value, second_id = left, idx

            base += right - top_value
            gain[top_id] += top_value - second_value

        return base + max(gain)

