class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # Binomial coefficients are used to count completions after the
        # first position at which a candidate is smaller than s.
        comb = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # A number having j set bits needs one operation to become j,
        # followed by the operations needed to reduce j to one.
        good = [False] * (L + 1)
        for j in range(1, L + 1):
            x = j
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[j] = (steps + 1 <= k)

        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = L - i - 1
                # Put zero here, and choose the remaining set bits freely.
                for total in range(1, L + 1):
                    need = total - used
                    if good[total] and 0 <= need <= remaining:
                        answer = (answer + comb[remaining][need]) % MOD
                used += 1

        return answer

