    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[0::2]
    d = vals[1::2]

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for ui, di in zip(u[1:], d[1:]):
            lo = max(0, h - di, lo - x)
            hi = min(ui, h, hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    high = min(ui + di for ui, di in zip(u, d)) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(sum(vals) - n * low)


