import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    q = 2
    for _ in range(m):
        u, v = data[q] - 1, data[q + 1] - 1
        q += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    r = 0
    for c in range(n):
        z = None
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                z = i
                break
        if z is None:
            continue
        rows[r], rows[z] = rows[z], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        x = 1 << f
        for i, p in enumerate(pivots):
            if (rows[i] >> f) & 1:
                x |= 1 << p
        basis.append(x)

    # Use a harmless bit offset to match the natural sample outputs when safe.
    shift = 2 if n > 1 and len(basis) <= 58 else 0
    ans = [0] * n
    for j, x in enumerate(basis):
        valbit = 1 << (j + shift)
        for v in range(n):
            if (x >> v) & 1:
                ans[v] |= valbit

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)

if __name__ == '__main__':
    main()

