from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        remaining = list(range(1, n + 1))
        odd = (n + 1) // 2
        even = n // 2

        def completions(o: int, e: int, last_parity: int) -> int:
            length = o + e
            if length == 0:
                return 1
            required = 1 - last_parity
            required_odd = ((length + 1) // 2
                            if required == 1 else length // 2)
            if o != required_odd or e != length - required_odd:
                return 0
            return min(cap, fact[o] * fact[e])

        result = []
        last = None
        for _ in range(n):
            chosen = False
            for i, value in enumerate(remaining):
                parity = value & 1
                if last is not None and parity == last:
                    continue

                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                amount = completions(new_odd, new_even, parity)
                if k > amount:
                    k -= amount
                else:
                    result.append(value)
                    remaining.pop(i)
                    odd, even, last = new_odd, new_even, parity
                    chosen = True
                    break
            if not chosen:
                return []
        return result

