class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        # p[i] is 10**i modulo k.
        p = [1] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        half_len = (n + 1) // 2
        coeff = [0] * half_len
        for i in range(half_len):
            j = n - 1 - i
            if i == j:
                coeff[i] = p[i]
            else:
                coeff[i] = (p[i] + p[j]) % k

        # suffix[i] is a bitset of residues obtainable by positions i onward.
        suffix = [0] * (half_len + 1)
        suffix[half_len] = 1                 # residue zero
        all_residues = (1 << k) - 1
        for i in range(half_len - 1, -1, -1):
            nxt = suffix[i + 1]
            a = coeff[i]
            reachable = 0
            for digit in range(10):
                shift = (digit * a) % k
                if shift == 0:
                    rotated = nxt
                else:
                    rotated = ((nxt << shift) |
                               (nxt >> (k - shift))) & all_residues
                reachable |= rotated
            suffix[i] = reachable

        remainder = 0
        first_half = []
        for i in range(half_len):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                new_remainder = (remainder + digit * coeff[i]) % k
                needed = (-new_remainder) % k
                if suffix[i + 1] & (1 << needed):
                    first_half.append(str(digit))
                    remainder = new_remainder
                    break

        h = ''.join(first_half)
        if n & 1:
            return h + h[-2::-1]
        return h + h[::-1]

