        for i in range(m - 1, -1, -1):
            a = coeff[i]
            nxt = suff[i+1]
            mask = 0
            for d in range(10):
                shift = (d*a) % k
                # rotate residue mask by shift
                mask |= ((nxt << shift) | (nxt >> (k-shift if shift else k))) & full if shift else nxt
