from typing import List
from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        # nxt[i] is the first position to the right whose value is larger.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        # A jump i -> nxt[i] skips a run whose required final value is nums[i].
        ends = [array('i', nxt)]
        costs = [array('q', (
            nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
            for i in range(n)
        ))]
        levels = n.bit_length()
        for _ in range(1, levels):
            pe, pc = ends[-1], costs[-1]
            ne = array('i', [0]) * n
            nc = array('q', [0]) * n
            for i in range(n):
                mid = pe[i]
                if mid < n:
                    ne[i] = pe[mid]
                    nc[i] = pc[i] + pc[mid]
                else:
                    ne[i] = n
                    nc[i] = pc[i]
            ends.append(ne)
            costs.append(nc)

        def required(left: int, right: int) -> int:
            pos = left
            total = 0
            for b in range(levels - 1, -1, -1):
                q = ends[b][pos]
                if q <= right:
                    total += costs[b][pos]
                    pos = q
            total += nums[pos] * (right - pos + 1) - (pref[right + 1] - pref[pos])
            return total

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if required(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

