import sys
from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, 2 * n + 2, 2)]

    # Functions are ordered from inner to outer by decreasing B/(A-1).
    # A=1 is treated as having an infinite ratio.
    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1 and c == 1:
            return 0
        if a == 1:
            return -1
        if c == 1:
            return 1
        left = b * (c - 1)
        right = d * (a - 1)
        if left > right:
            return -1
        if left < right:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))
    neg_inf = -10 ** 100
    dp = [neg_inf] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for used in range(k, 0, -1):
            candidate = a * dp[used - 1] + b
            if candidate > dp[used]:
                dp[used] = candidate
    print(dp[k])


if __name__ == '__main__':
    main()

